function mkFrame(name, x, y, w, h) {
  const f = figma.createFrame();
  f.name = name;
  f.x = x; f.y = y;
  f.resize(w, h);
  f.fills = [];
  f.clipsContent = true;
  page.appendChild(f);
  return f;
}
function mkSection(parent, name, w, h, fill) {
  const f = figma.createFrame();
  f.name = name;
  f.resize(w, h);
  f.fills = fill ? [{type:'SOLID', color: fill}] : [];
  f.clipsContent = true;
  f.layoutMode = 'VERTICAL';
  f.primaryAxisAlignItems = 'CENTER';
  f.counterAxisAlignItems = 'CENTER';
  f.itemSpacing = 0;
  parent.appendChild(f);
  return f;
}
function mkContent(section, name, w, h) {
  const f = figma.createFrame();
