function inst(id, x, y, parent, w) {
  const c = figma.getNodeById(id);
  const i = c.createInstance();
  parent.appendChild(i);
  i.x = x; i.y = y;
  if (w && i.width !== w) i.resize(w, i.height * w / i.width);
  return i;
}
function instCover(id, x, y, w, h, parent) {
  const c = figma.getNodeById(id);
  const i = c.createInstance();
  parent.appendChild(i);
  const fills = JSON.parse(JSON.stringify(i.fills));
  if (fills.length && fills[0].type==='IMAGE') { fills[0].scaleMode='FILL'; i.fills=fills; }
  i.resize(w, h);
  i.x = x; i.y = y;
  return i;
}
function text(parent, str, fontSize, style, color, x, y) {
  const t = figma.createText();
  t.fontName = {family:'Source Sans Pro', style};
  t.fontSize = fontSize;
  t.characters = str;
  t.fills = [{type:'SOLID', color}];
  t.x = x; t.y = y;
  parent.appendChild(t);
  return t;
}
function rect(parent, x, y, w, h, fill, radius) {
  const r = figma.createRectangle();
  r.x = x; r.y = y; r.resize(w, h);
  r.fills = fill ? [{type:'SOLID', color: fill}] : [];
  if (radius) r.cornerRadius = radius;
  parent.appendChild(r);
  return r;
}
function iconBtn(parent, name, x, y, w, h, label, iconId, fill, labelColor, iconColor, radius) {
  const f = figma.createFrame();
  f.name = name;
  f.resize(w, h); f.x = x; f.y = y;
  f.fills = [{type:'SOLID', color: fill}];
  f.cornerRadius = radius != null ? radius : 10;
  parent.appendChild(f);
  const t = text(f, label, 18, 'Bold', labelColor, 0, 0);
  const labelW = t.width;
  const iconW = 24, gap = 10;
  const total = iconId ? iconW + gap + labelW : labelW;
  const startX = (w - total) / 2;
  let cx = startX;
  if (iconId) {
    const ic = inst(iconId, cx, (h-24)/2, f, 24);
    for (const v of ic.findAll(n=>n.type==='VECTOR')) v.fills=[{type:'SOLID',color:iconColor}];
    cx += iconW + gap;
  }
  t.x = cx; t.y = (h - t.height)/2;
  return f;
}
