function text(parent, str, fontSize, style, color, x, y) {
  const t = figma.createText();
  t.fontName = {family:'Source Sans Pro', style};
  t.fontSize = fontSize;
  t.characters = str;
  t.fills = [{type:'SOLID', color}];
  t.x = x; t.y = y;
  parent.appendChild(t);
  return t;
}
function makeComponent(parent, name, w, h, x, y) {
  const c = figma.createComponent();
  c.name = name;
  c.resize(w, h);
  c.x = x; c.y = y;
  c.fills = [];
  c.clipsContent = false;
  parent.appendChild(c);
  return c;
}
function instInto(id, x, y, parent, w) {
  const i = figma.getNodeById(id).createInstance();
  parent.appendChild(i);
  i.x = x; i.y = y;
  if (w && i.width !== w) i.resize(w, i.height * w / i.width);
  return i;
}
